# PostgreSQL problems. (tier, topic, title, prompt, hint, solution, explanation, ordered, similar_url_or_None)
LC="https://leetcode.com/problems/"
P=[
# ---------- EASY ----------
("easy","aggregation","Policies per product",
"The underwriting team wants a quick count of how many policies exist for each product line. Using the policies table, return product and n (policy count), highest count first, ties broken by product.",
"GROUP BY product, then ORDER BY the count.",
"SELECT product, COUNT(*) AS n\nFROM policies\nGROUP BY product\nORDER BY n DESC, product;",
"Basic GROUP BY. The tie-break on product makes the order deterministic.",True,None),
("easy","aggregation","Written premium by state",
"Using the policies table, return each state and total_premium (sum of premium, rounded to 2 decimals), sorted by state.",
"SUM then ROUND(x, 2). premium is NUMERIC so ROUND works directly.",
"SELECT state, ROUND(SUM(premium), 2) AS total_premium\nFROM policies\nGROUP BY state\nORDER BY state;",
"Aggregate, then round. In Postgres ROUND(value, digits) needs NUMERIC; ROUND(double precision, int) does not exist, so cast with ::numeric when needed.",True,None),
("easy","filtering","Open claims with large reserves",
"Claims ops wants every OPEN claim whose reserve_amount is above 3000. From the claims table, return claim_id and reserve_amount ordered by claim_id.",
"Two conditions joined with AND.",
"SELECT claim_id, reserve_amount\nFROM claims\nWHERE status = 'OPEN' AND reserve_amount > 3000\nORDER BY claim_id;",
"Straight filter. String comparison is case-sensitive in Postgres (use ILIKE or lower() for case-insensitive).",True,None),
("easy","joins","Claims with their product",
"Tables: claims, policies. For each claim show claim_id, the product of the policy it was filed against, and paid_amount. Order by claim_id.",
"claims.policy_id references policies.policy_id.",
"SELECT c.claim_id, p.product, c.paid_amount\nFROM claims c\nJOIN policies p ON p.policy_id = c.policy_id\nORDER BY c.claim_id;",
"INNER JOIN on the foreign key.",True,None),
("easy","joins","Customers who never filed a claim",
"Tables: customers, policies, claims. Return the name of every customer who has never had a claim on any of their policies. Order by name.",
"Anti-join: NOT EXISTS (policies joined to claims for that customer).",
"SELECT cu.name\nFROM customers cu\nWHERE NOT EXISTS (\n  SELECT 1 FROM policies p\n  JOIN claims c ON c.policy_id = p.policy_id\n  WHERE p.customer_id = cu.customer_id)\nORDER BY cu.name;",
"Anti-join. NOT EXISTS is NULL-safe; NOT IN silently returns nothing if the subquery yields a NULL.",True,LC+"customers-who-never-order/"),
("easy","aggregation","Average severity by cause",
"From claims, compute avg_incurred per cause, where incurred = paid_amount + reserve_amount, rounded to 2 decimals. Sort by avg_incurred descending.",
"AVG(paid_amount + reserve_amount).",
"SELECT cause, ROUND(AVG(paid_amount + reserve_amount), 2) AS avg_incurred\nFROM claims\nGROUP BY cause\nORDER BY avg_incurred DESC;",
"Severity = average loss per claim.",True,None),
("easy","having","States with 3+ customers",
"From customers, return state and n for states that have at least 3 customers. Order by state.",
"HAVING filters groups after aggregation.",
"SELECT state, COUNT(*) AS n\nFROM customers\nGROUP BY state\nHAVING COUNT(*) >= 3\nORDER BY state;",
"WHERE filters rows before grouping; HAVING filters groups after.",True,None),
("easy","dates","Claims reported within a week",
"From claims, return claim_id and lag_days (report_date - loss_date) for claims reported within 7 days of the loss. Order by claim_id.",
"In Postgres, DATE - DATE returns an integer number of days.",
"SELECT claim_id, report_date - loss_date AS lag_days\nFROM claims\nWHERE report_date - loss_date <= 7\nORDER BY claim_id;",
"date - date = integer days. timestamp - timestamp = INTERVAL (use EXTRACT(EPOCH FROM ...) or ::date). Databricks uses datediff(end, start).",True,None),
("easy","dates","Quotes per month",
"From quotes, return month (first day of the month, as a date) and quotes (count). Order by month.",
"DATE_TRUNC('month', d) returns a timestamp; cast with ::date.",
"SELECT DATE_TRUNC('month', quote_date)::date AS month, COUNT(*) AS quotes\nFROM quotes\nGROUP BY 1\nORDER BY 1;",
"DATE_TRUNC is the standard month bucket in Postgres, Databricks and Snowflake. Keeping it a date (not a 'YYYY-MM' string) keeps sorting and joining easy.",True,None),
("easy","case","Bind rate by product",
"From quotes (bound is BOOLEAN), return product and bind_rate_pct = % of quotes bound, 1 decimal. Order by product.",
"COUNT(*) FILTER (WHERE bound) / COUNT(*), or AVG(bound::int).",
"SELECT product,\n  ROUND(100.0 * COUNT(*) FILTER (WHERE bound) / COUNT(*), 1) AS bind_rate_pct\nFROM quotes\nGROUP BY product\nORDER BY product;",
"FILTER (WHERE ...) is Postgres's clean conditional aggregate. 100.0 forces numeric division (int/int truncates in Postgres).",True,None),
("easy","case","Premium buckets",
"From policies, count policies per bucket: '<1000', '1000-2499', '2500+'. Return bucket and n ordered by bucket.",
"CASE WHEN ... END, then GROUP BY 1.",
"SELECT CASE WHEN premium < 1000 THEN '<1000'\n            WHEN premium < 2500 THEN '1000-2499'\n            ELSE '2500+' END AS bucket,\n       COUNT(*) AS n\nFROM policies\nGROUP BY 1\nORDER BY 1;",
"CASE evaluates top-down, so the second branch only sees premium >= 1000.",True,None),
("easy","distinct","Distinct buyers",
"From orders, how many distinct users have at least one order with status 'complete'? Return one column buyers.",
"COUNT(DISTINCT ...).",
"SELECT COUNT(DISTINCT user_id) AS buyers\nFROM orders\nWHERE status = 'complete';",
"COUNT(DISTINCT) vs COUNT(*) is a classic trap.",False,None),
("easy","self-join","Employee and manager",
"From employees (manager_id references emp_id), return name and manager (the manager's name, NULL for the top person). Order by emp_id.",
"LEFT JOIN employees to itself.",
"SELECT e.name, m.name AS manager\nFROM employees e\nLEFT JOIN employees m ON m.emp_id = e.manager_id\nORDER BY e.emp_id;",
"LEFT JOIN keeps the person with no manager.",True,LC+"employees-earning-more-than-their-managers/"),
("easy","aggregation","Highest salary per department",
"From employees, return dept and max_salary. Order by dept.",
"GROUP BY dept.",
"SELECT dept, MAX(salary) AS max_salary\nFROM employees\nGROUP BY dept\nORDER BY dept;",
"To return the person, you need DISTINCT ON or a window (see medium).",True,LC+"department-highest-salary/"),
("easy","null","Referral default",
"From customers, return name and referrer (referred_by, or 0 when NULL). Order by customer_id.",
"COALESCE.",
"SELECT name, COALESCE(referred_by, 0) AS referrer\nFROM customers\nORDER BY customer_id;",
"COALESCE returns the first non-NULL argument.",True,None),
("easy","filtering","Active policies in CA or TX",
"From policies, return policy_id for ACTIVE policies in CA or TX. Order by policy_id.",
"IN ('CA','TX').",
"SELECT policy_id\nFROM policies\nWHERE status = 'ACTIVE' AND state IN ('CA', 'TX')\nORDER BY policy_id;",
"Mixing AND with OR without parentheses is a common bug; IN avoids it.",True,None),
("easy","aggregation","Refund share",
"From orders, return refund_pct = percent of all orders with status 'refunded', 1 decimal.",
"COUNT(*) FILTER (WHERE status = 'refunded').",
"SELECT ROUND(100.0 * COUNT(*) FILTER (WHERE status = 'refunded') / COUNT(*), 1) AS refund_pct\nFROM orders;",
"Conditional aggregation with FILTER.",False,None),
("easy","union","Earliest touchpoint dates",
"Tables: quotes, policies. Return a single column d with the 5 earliest distinct dates on which a quote was created (quote_date) or a policy became effective (effective_date).",
"UNION removes duplicates; UNION ALL keeps them. Postgres requires an alias on a subquery in FROM (older versions).",
"SELECT d FROM (\n  SELECT quote_date AS d FROM quotes\n  UNION\n  SELECT effective_date FROM policies\n) t\nORDER BY d\nLIMIT 5;",
"UNION dedupes (costly on big data); use UNION ALL when rows are known distinct.",True,None),
("easy","aggregation","Users by country and plan",
"From users, return country, plan, n. Order by country, plan.",
"GROUP BY two columns.",
"SELECT country, plan, COUNT(*) AS n\nFROM users\nGROUP BY country, plan\nORDER BY country, plan;",
"Multi-column grouping.",True,None),
("easy","subquery","Above-average premium",
"From policies, return policy_id and premium for policies whose premium is above the average premium of all policies. Order by policy_id.",
"Scalar subquery in WHERE.",
"SELECT policy_id, premium\nFROM policies\nWHERE premium > (SELECT AVG(premium) FROM policies)\nORDER BY policy_id;",
"A scalar subquery is evaluated once.",True,None),
# ---------- MEDIUM ----------
("medium","window","Rank premium within state",
"From policies, return state, policy_id, premium and rnk = dense rank of premium within the state (highest = 1). Order by state, rnk, policy_id.",
"DENSE_RANK() OVER (PARTITION BY state ORDER BY premium DESC).",
"SELECT state, policy_id, premium,\n  DENSE_RANK() OVER (PARTITION BY state ORDER BY premium DESC) AS rnk\nFROM policies\nORDER BY state, rnk, policy_id;",
"ROW_NUMBER: unique; RANK: gaps after ties; DENSE_RANK: no gaps.",True,LC+"rank-scores/"),
("medium","top-n","Top 2 earners per department",
"From employees, return name, dept, salary for the two highest-paid people in each department. Order by dept, salary desc.",
"ROW_NUMBER in a CTE, then filter rn <= 2.",
"WITH r AS (\n  SELECT name, dept, salary,\n    ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC) AS rn\n  FROM employees)\nSELECT name, dept, salary FROM r\nWHERE rn <= 2\nORDER BY dept, salary DESC;",
"Top-N per group = window rank + filter. You can't filter a window function in WHERE of the same SELECT (Databricks/Snowflake have QUALIFY; Postgres doesn't).",True,LC+"department-top-three-salaries/"),
("medium","running","Running written premium",
"From policies, ordered by effective_date then policy_id, return policy_id, effective_date, premium and running = cumulative premium.",
"SUM() OVER (ORDER BY ... ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW).",
"SELECT policy_id, effective_date, premium,\n  SUM(premium) OVER (ORDER BY effective_date, policy_id\n    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running\nFROM policies\nORDER BY effective_date, policy_id;",
"An explicit ROWS frame avoids RANGE's tie behavior.",True,LC+"last-person-to-fit-in-the-bus/"),
("medium","lag","Renewal rate change",
"From policies, a renewal is a customer's next policy of the same product. For each renewal return customer_id, policy_id, prev (prior term's premium) and pct_change (1 decimal). Order by customer_id, policy_id.",
"LAG(premium) OVER (PARTITION BY customer_id, product ORDER BY effective_date).",
"WITH x AS (\n  SELECT customer_id, policy_id, premium,\n    LAG(premium) OVER (PARTITION BY customer_id, product ORDER BY effective_date) AS prev\n  FROM policies)\nSELECT customer_id, policy_id, prev,\n  ROUND(100.0 * (premium - prev) / prev, 1) AS pct_change\nFROM x\nWHERE prev IS NOT NULL\nORDER BY customer_id, policy_id;",
"Renewal rate change is a core pricing metric.",True,None),
("medium","dedup","Detect duplicate logins",
"From logins, return user_id, raw_rows and distinct_days per user. Order by user_id.",
"COUNT(*) vs COUNT(DISTINCT login_date).",
"SELECT user_id, COUNT(*) AS raw_rows, COUNT(DISTINCT login_date) AS distinct_days\nFROM logins\nGROUP BY user_id\nORDER BY user_id;",
"Measure duplication before fixing it.",True,None),
("medium","dedup","Latest claim per policy",
"From claims, for each policy_id keep only the most recently reported claim (ties: higher claim_id). Return policy_id, claim_id, report_date ordered by policy_id.",
"DISTINCT ON (policy_id) with ORDER BY policy_id, report_date DESC, claim_id DESC.",
"SELECT DISTINCT ON (policy_id) policy_id, claim_id, report_date\nFROM claims\nORDER BY policy_id, report_date DESC, claim_id DESC;",
"DISTINCT ON is Postgres's shortcut for 'first row per group'. Portable version: ROW_NUMBER() ... WHERE rn = 1.",True,None),
("medium","joins","Loss ratio by product",
"Tables: policies, claims. Loss ratio = SUM(paid_amount + reserve_amount) / SUM(premium) per product, 3 decimals; products with no claims show 0. Return product, loss_ratio ordered by product.",
"Fan-out trap: joining policies to claims first duplicates premium. Aggregate each side separately.",
"WITH prem AS (\n  SELECT product, SUM(premium) AS p FROM policies GROUP BY product),\nloss AS (\n  SELECT p.product, SUM(c.paid_amount + c.reserve_amount) AS l\n  FROM claims c JOIN policies p ON p.policy_id = c.policy_id\n  GROUP BY p.product)\nSELECT prem.product, ROUND(COALESCE(l, 0) / p, 3) AS loss_ratio\nFROM prem LEFT JOIN loss USING (product)\nORDER BY prem.product;",
"Aggregate each fact to the shared grain before joining. Note this is written premium, not earned.",True,None),
("medium","pivot","Claims by cause pivot",
"Tables: claims, policies. One row per product with columns water, fire, theft, injury, collision = number of claims of that cause. Order by product.",
"COUNT(*) FILTER (WHERE cause = 'Water') AS water, ...",
"SELECT p.product,\n  COUNT(*) FILTER (WHERE cause = 'Water') AS water,\n  COUNT(*) FILTER (WHERE cause = 'Fire') AS fire,\n  COUNT(*) FILTER (WHERE cause = 'Theft') AS theft,\n  COUNT(*) FILTER (WHERE cause = 'Injury') AS injury,\n  COUNT(*) FILTER (WHERE cause = 'Collision') AS collision\nFROM claims c\nJOIN policies p ON p.policy_id = c.policy_id\nGROUP BY p.product\nORDER BY p.product;",
"FILTER pivots are clean in Postgres; SUM(CASE ...) is the portable form.",True,LC+"reformat-department-table/"),
("medium","window","Share of state premium",
"From policies, return policy_id, state and pct_of_state = premium as % of its state's total premium (1 decimal). Order by state, policy_id.",
"SUM(premium) OVER (PARTITION BY state).",
"SELECT policy_id, state,\n  ROUND(100.0 * premium / SUM(premium) OVER (PARTITION BY state), 1) AS pct_of_state\nFROM policies\nORDER BY state, policy_id;",
"Window aggregates keep row detail without a self-join.",True,None),
("medium","dates","Monthly revenue with MoM growth",
"From orders (status 'complete' only), return mon (month start date), rev (2 decimals) and mom_pct (% change vs previous month, 1 decimal). Order by mon.",
"Aggregate by DATE_TRUNC in a CTE, then LAG.",
"WITH m AS (\n  SELECT DATE_TRUNC('month', order_date)::date AS mon, SUM(amount) AS rev\n  FROM orders WHERE status = 'complete'\n  GROUP BY 1)\nSELECT mon, ROUND(rev, 2) AS rev,\n  ROUND(100.0 * (rev - LAG(rev) OVER (ORDER BY mon)) / LAG(rev) OVER (ORDER BY mon), 1) AS mom_pct\nFROM m\nORDER BY mon;",
"Aggregate first, window second.",True,None),
("medium","self-join","Cross-state referrals",
"From customers (referred_by references customer_id), return referrer and referee names where the two live in different states. Order by referrer, referee.",
"Join customers to itself on c.referred_by = r.customer_id.",
"SELECT r.name AS referrer, c.name AS referee\nFROM customers c\nJOIN customers r ON r.customer_id = c.referred_by\nWHERE r.state <> c.state\nORDER BY referrer, referee;",
"Self joins model relationships within one entity.",True,None),
("medium","funnel","Event funnel",
"From events, return one row with columns visit, signup, add_to_cart, purchase = distinct users who did each event_type.",
"COUNT(DISTINCT user_id) FILTER (WHERE event_type = ...).",
"SELECT\n  COUNT(DISTINCT user_id) FILTER (WHERE event_type = 'visit') AS visit,\n  COUNT(DISTINCT user_id) FILTER (WHERE event_type = 'signup') AS signup,\n  COUNT(DISTINCT user_id) FILTER (WHERE event_type = 'add_to_cart') AS add_to_cart,\n  COUNT(DISTINCT user_id) FILTER (WHERE event_type = 'purchase') AS purchase\nFROM events;",
"A loose funnel. A strict funnel requires steps in order (see hard).",False,None),
("medium","funnel","Quote funnel by month",
"From quotes, return mon (month start), quotes, binds and bind_pct (1 decimal). Order by mon.",
"COUNT(*) FILTER (WHERE bound).",
"SELECT DATE_TRUNC('month', quote_date)::date AS mon,\n  COUNT(*) AS quotes,\n  COUNT(*) FILTER (WHERE bound) AS binds,\n  ROUND(100.0 * COUNT(*) FILTER (WHERE bound) / COUNT(*), 1) AS bind_pct\nFROM quotes\nGROUP BY 1\nORDER BY 1;",
"Quote metrics are daily work at an insurtech.",True,LC+"monthly-transactions-i/"),
("medium","subquery","Above their state's average",
"Tables: customers, policies. Return name, state and tot (total premium across the customer's policies, 2 decimals) for customers whose total exceeds the average customer total in their state. Order by state, name.",
"CTE of customer totals, then AVG(tot) OVER (PARTITION BY state).",
"WITH t AS (\n  SELECT c.customer_id, c.name, c.state, SUM(p.premium) AS tot\n  FROM customers c JOIN policies p ON p.customer_id = c.customer_id\n  GROUP BY c.customer_id, c.name, c.state),\ns AS (SELECT *, AVG(tot) OVER (PARTITION BY state) AS st_avg FROM t)\nSELECT name, state, ROUND(tot, 2) AS tot\nFROM s WHERE tot > st_avg\nORDER BY state, name;",
"Correlated-subquery problems are often cleaner as window aggregates.",True,None),
("medium","window","Second highest salary",
"From employees, return second_highest = the second highest distinct salary (NULL if it doesn't exist).",
"DENSE_RANK = 2, or MAX(salary) WHERE salary < MAX.",
"SELECT MAX(salary) AS second_highest\nFROM employees\nWHERE salary < (SELECT MAX(salary) FROM employees);",
"The DENSE_RANK version generalizes to Nth highest.",False,LC+"second-highest-salary/"),
("medium","dates","Days since last loss",
"Tables: claims, policies. For each customer with at least one claim, return customer_id, last_loss (latest loss_date) and days_since = days from last_loss to DATE '2026-06-30'. Order by customer_id.",
"DATE '2026-06-30' - MAX(loss_date).",
"SELECT p.customer_id, MAX(c.loss_date) AS last_loss,\n  DATE '2026-06-30' - MAX(c.loss_date) AS days_since\nFROM claims c\nJOIN policies p ON p.policy_id = c.policy_id\nGROUP BY p.customer_id\nORDER BY p.customer_id;",
"Typed literals (DATE '...') or '...'::date avoid implicit text comparisons.",True,None),
("medium","window","3-order moving average",
"From orders, per user return user_id, order_id, order_date and ma3 = average amount of the current and 2 previous orders (by order_date, order_id), 2 decimals. Order by user_id, order_date, order_id.",
"AVG() OVER (PARTITION BY user_id ORDER BY ... ROWS BETWEEN 2 PRECEDING AND CURRENT ROW).",
"SELECT user_id, order_id, order_date,\n  ROUND(AVG(amount) OVER (PARTITION BY user_id ORDER BY order_date, order_id\n    ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 2) AS ma3\nFROM orders\nORDER BY user_id, order_date, order_id;",
"ROWS counts rows; RANGE uses value distance (in Postgres RANGE can take an INTERVAL offset on dates).",True,LC+"restaurant-growth/"),
("medium","joins","Cross-sell gaps",
"Tables: customers, policies. Count every (customer, product) combination where the customer has never held a policy of that product (products = distinct products in policies). Return one column gaps.",
"CROSS JOIN customers with distinct products, then NOT EXISTS.",
"SELECT COUNT(*) AS gaps\nFROM customers c\nCROSS JOIN (SELECT DISTINCT product FROM policies) pr\nWHERE NOT EXISTS (\n  SELECT 1 FROM policies p\n  WHERE p.customer_id = c.customer_id AND p.product = pr.product);",
"A densification pattern: build all combinations, then subtract what exists.",False,None),
("medium","case","Tenure segment",
"From policies, return customer_id, terms (number of policies) and seg: 'new' (1), 'renewing' (2), 'loyal' (3+). Order by customer_id.",
"COUNT(*) then CASE on it.",
"SELECT customer_id, COUNT(*) AS terms,\n  CASE WHEN COUNT(*) = 1 THEN 'new'\n       WHEN COUNT(*) = 2 THEN 'renewing'\n       ELSE 'loyal' END AS seg\nFROM policies\nGROUP BY customer_id\nORDER BY customer_id;",
"CASE over aggregates is allowed in SELECT.",True,None),
("medium","ranking","Severity percentile",
"From claims, return claim_id, cause, incurred (paid + reserve) and pr = PERCENT_RANK of incurred within the cause (2 decimals). Order by cause, pr, claim_id.",
"PERCENT_RANK() returns double precision, so cast to numeric before ROUND.",
"SELECT claim_id, cause, paid_amount + reserve_amount AS incurred,\n  ROUND((PERCENT_RANK() OVER (PARTITION BY cause ORDER BY paid_amount + reserve_amount))::numeric, 2) AS pr\nFROM claims\nORDER BY cause, pr, claim_id;",
"Postgres gotcha: ROUND(double precision, int) doesn't exist; cast with ::numeric.",True,None),
("medium","dates","Policies in force on a date",
"From policies, how many non-cancelled policies were in force on 2025-06-30 (effective_date <= date < expiration_date)? Return in_force.",
"Half-open interval; compare to DATE '2025-06-30'.",
"SELECT COUNT(*) AS in_force\nFROM policies\nWHERE effective_date <= DATE '2025-06-30'\n  AND expiration_date > DATE '2025-06-30'\n  AND status <> 'CANCELLED';",
"Half-open [start, end) avoids double counting renewal days. Postgres also has daterange(effective_date, expiration_date) @> date.",False,None),
("medium","cte","First quote bound",
"From quotes, return customer_id of customers whose earliest quote (by quote_date, then quote_id) was bound. Order by customer_id.",
"DISTINCT ON (customer_id) ... ORDER BY customer_id, quote_date, quote_id.",
"SELECT customer_id FROM (\n  SELECT DISTINCT ON (customer_id) customer_id, bound\n  FROM quotes\n  ORDER BY customer_id, quote_date, quote_id) f\nWHERE bound\nORDER BY customer_id;",
"First-touch analysis with DISTINCT ON.",True,LC+"immediate-food-delivery-ii/"),
("medium","aggregation","Orders-per-user distribution",
"Tables: users, orders. How many users placed 0, 1, 2, ... complete orders? Include users with zero. Return orders, users ordered by orders.",
"LEFT JOIN with the status filter in the ON clause.",
"WITH c AS (\n  SELECT u.user_id, COUNT(o.order_id) AS n\n  FROM users u\n  LEFT JOIN orders o ON o.user_id = u.user_id AND o.status = 'complete'\n  GROUP BY u.user_id)\nSELECT n AS orders, COUNT(*) AS users\nFROM c GROUP BY n ORDER BY n;",
"A filter on the right table in WHERE turns a LEFT JOIN into an INNER JOIN.",True,None),
# ---------- HARD ----------
("hard","gaps-islands","Longest login streak",
"From logins (may contain duplicate rows per day), return user_id and longest_streak = longest run of consecutive login days. Order by user_id.",
"Dedupe, then login_date - ROW_NUMBER()::int is constant within a streak.",
"WITH d AS (SELECT DISTINCT user_id, login_date FROM logins),\ng AS (\n  SELECT user_id, login_date,\n    login_date - (ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY login_date))::int AS grp\n  FROM d)\nSELECT user_id, MAX(len) AS longest_streak FROM (\n  SELECT user_id, grp, COUNT(*) AS len FROM g GROUP BY user_id, grp) s\nGROUP BY user_id\nORDER BY user_id;",
"The canonical gaps-and-islands trick. date - integer = date in Postgres. Dedupe first or duplicates break it.",True,LC+"consecutive-numbers/"),
("hard","gaps-islands","Continuous coverage periods",
"From policies, merge each customer's overlapping or touching policy terms into continuous coverage periods. Return customer_id, cover_start, cover_end ordered by customer_id, cover_start.",
"New island when effective_date > running MAX(expiration_date) of earlier rows.",
"WITH t AS (\n  SELECT customer_id, policy_id, effective_date AS s, expiration_date AS e,\n    MAX(expiration_date) OVER (PARTITION BY customer_id ORDER BY effective_date, policy_id\n      ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS prev_end\n  FROM policies),\ng AS (\n  SELECT *, SUM(CASE WHEN prev_end IS NULL OR s > prev_end THEN 1 ELSE 0 END)\n    OVER (PARTITION BY customer_id ORDER BY s, policy_id ROWS UNBOUNDED PRECEDING) AS isl\n  FROM t)\nSELECT customer_id, MIN(s) AS cover_start, MAX(e) AS cover_end\nFROM g GROUP BY customer_id, isl\nORDER BY customer_id, cover_start;",
"Interval merging: the insurance flavor of gaps-and-islands (lapse detection).",True,None),
("hard","cohort","Monthly retention cohorts",
"Tables: users, orders. For users grouped by signup month (cohort, month start date), count distinct users with a complete order in month offset 0, 1 and 2 after signup (m0, m1, m2). Order by cohort.",
"Offset = months between DATE_TRUNC('month', order_date) and DATE_TRUNC('month', signup_date); use EXTRACT on AGE() or year*12+month.",
"WITH o AS (\n  SELECT u.user_id, DATE_TRUNC('month', u.signup_date)::date AS cohort,\n    (EXTRACT(YEAR FROM o.order_date) * 12 + EXTRACT(MONTH FROM o.order_date))\n    - (EXTRACT(YEAR FROM u.signup_date) * 12 + EXTRACT(MONTH FROM u.signup_date)) AS k\n  FROM users u\n  JOIN orders o ON o.user_id = u.user_id AND o.status = 'complete')\nSELECT cohort,\n  COUNT(DISTINCT user_id) FILTER (WHERE k = 0) AS m0,\n  COUNT(DISTINCT user_id) FILTER (WHERE k = 1) AS m1,\n  COUNT(DISTINCT user_id) FILTER (WHERE k = 2) AS m2\nFROM o GROUP BY cohort ORDER BY cohort;",
"Month index = year*12 + month is robust; AGE() gives months only within the year part.",True,None),
("hard","recursive","Org chart depth",
"From employees, return emp_id, name, lvl (top = 1) and path of names from the top joined with ' > '. Order by emp_id.",
"WITH RECURSIVE; anchor is manager_id IS NULL. Cast the path to text in the anchor.",
"WITH RECURSIVE t AS (\n  SELECT emp_id, name, 1 AS lvl, name::text AS path\n  FROM employees WHERE manager_id IS NULL\n  UNION ALL\n  SELECT e.emp_id, e.name, t.lvl + 1, t.path || ' > ' || e.name\n  FROM employees e JOIN t ON e.manager_id = t.emp_id)\nSELECT emp_id, name, lvl, path FROM t ORDER BY emp_id;",
"Recursive CTE = anchor + recursive member. Postgres requires matching column types between them.",True,None),
("hard","spine","Month spine with zero months",
"Tables: orders. For every month start from 2025-01-01 through 2025-12-01, count complete orders (months with none show 0). Return month_start, orders.",
"generate_series(start, end, INTERVAL '1 month'), then LEFT JOIN.",
"SELECT m::date AS month_start, COUNT(o.order_id) AS orders\nFROM generate_series(DATE '2025-01-01', DATE '2025-12-01', INTERVAL '1 month') m\nLEFT JOIN orders o\n  ON DATE_TRUNC('month', o.order_date) = m AND o.status = 'complete'\nGROUP BY m\nORDER BY m;",
"Date spines prevent missing periods (dbt_utils.date_spine; sequence()/explode in Databricks).",True,None),
("hard","funnel","Strict ordered funnel",
"From events, return user_id of users who did visit, signup, add_to_cart and purchase with each step's first date on or after the previous step's first date. Order by user_id.",
"MIN(event_date) FILTER (WHERE event_type = ...) per user, then compare.",
"WITH s AS (\n  SELECT user_id,\n    MIN(event_date) FILTER (WHERE event_type = 'visit') AS v,\n    MIN(event_date) FILTER (WHERE event_type = 'signup') AS su,\n    MIN(event_date) FILTER (WHERE event_type = 'add_to_cart') AS a,\n    MIN(event_date) FILTER (WHERE event_type = 'purchase') AS p\n  FROM events GROUP BY user_id)\nSELECT user_id FROM s\nWHERE v <= su AND su <= a AND a <= p\nORDER BY user_id;",
"Comparisons with NULL are unknown and get filtered out, which is what we want.",True,None),
("hard","earned","Earned premium in 2025",
"From policies (excluding CANCELLED), compute earned_2025 = pro-rata premium earned during calendar 2025, 2 decimals. Earned = premium * overlap_days / term_days.",
"overlap = GREATEST(0, LEAST(expiration_date, DATE '2026-01-01') - GREATEST(effective_date, DATE '2025-01-01')).",
"SELECT ROUND(SUM(premium * GREATEST(0,\n    LEAST(expiration_date, DATE '2026-01-01') - GREATEST(effective_date, DATE '2025-01-01'))\n  / (expiration_date - effective_date)::numeric), 2) AS earned_2025\nFROM policies\nWHERE status <> 'CANCELLED';",
"Interval overlap formula. LEAST/GREATEST are scalar; date - date is integer, so cast the denominator to numeric.",False,None),
("hard","window","Cumulative reported claims",
"From claims, for each report_date return cum_claims (claims reported up to and including that date) and cum_incurred (2 decimals). Order by report_date.",
"Aggregate per date first, then running SUM.",
"WITH d AS (\n  SELECT report_date, COUNT(*) AS n, SUM(paid_amount + reserve_amount) AS inc\n  FROM claims GROUP BY report_date)\nSELECT report_date,\n  SUM(n) OVER (ORDER BY report_date) AS cum_claims,\n  ROUND(SUM(inc) OVER (ORDER BY report_date), 2) AS cum_incurred\nFROM d ORDER BY report_date;",
"Aggregate-then-window avoids RANGE tie surprises.",True,None),
("hard","top-n","Top cause per state",
"Tables: claims, policies. For each policy state, return the cause with the highest total incurred (ties: alphabetical) as state, cause, inc (2 decimals). Order by state.",
"Aggregate, then DISTINCT ON (state) ORDER BY state, inc DESC, cause.",
"SELECT DISTINCT ON (p.state) p.state, c.cause,\n  ROUND(SUM(c.paid_amount + c.reserve_amount), 2) AS inc\nFROM claims c JOIN policies p ON p.policy_id = c.policy_id\nGROUP BY p.state, c.cause\nORDER BY p.state, SUM(c.paid_amount + c.reserve_amount) DESC, c.cause;",
"DISTINCT ON works after GROUP BY: one row per state, chosen by the ORDER BY.",True,None),
("hard","self-join","Overlapping terms",
"From policies, return pairs (customer_id, p1, p2) of policies of the same customer and product whose terms overlap, with p1 < p2. Order by all columns.",
"a.effective_date < b.expiration_date AND b.effective_date < a.expiration_date.",
"SELECT a.customer_id, a.policy_id AS p1, b.policy_id AS p2\nFROM policies a\nJOIN policies b ON a.customer_id = b.customer_id AND a.product = b.product\n  AND a.policy_id < b.policy_id\n  AND a.effective_date < b.expiration_date AND b.effective_date < a.expiration_date\nORDER BY 1, 2, 3;",
"Overlap check is a good dbt singular test. Postgres alternative: daterange(a...) && daterange(b...).",True,None),
("hard","dedup","Near-duplicate claims",
"From claims, return pairs c1 < c2 with policy_id where both claims are on the same policy, same cause, and loss dates within 3 days. Order by c1, c2.",
"Self join; ABS(a.loss_date - b.loss_date) <= 3.",
"SELECT a.claim_id AS c1, b.claim_id AS c2, a.policy_id\nFROM claims a\nJOIN claims b ON a.policy_id = b.policy_id AND a.cause = b.cause\n  AND a.claim_id < b.claim_id\n  AND ABS(a.loss_date - b.loss_date) <= 3\nORDER BY 1, 2;",
"Fuzzy dedup is also a fraud signal.",True,LC+"duplicate-emails/"),
("hard","window","Gap between terms",
"From policies, for each customer's consecutive policies (by effective_date, policy_id) return customer_id, policy_id and gap_days = effective_date minus the previous policy's expiration_date (negative = overlap). Skip each customer's first policy.",
"LAG(expiration_date) OVER (...).",
"WITH x AS (\n  SELECT customer_id, policy_id, effective_date,\n    LAG(expiration_date) OVER (PARTITION BY customer_id ORDER BY effective_date, policy_id) AS prev_exp\n  FROM policies)\nSELECT customer_id, policy_id, effective_date - prev_exp AS gap_days\nFROM x WHERE prev_exp IS NOT NULL\nORDER BY customer_id, policy_id;",
"Lapse analysis for retention.",True,None),
("hard","cohort","Bind within 30 days of signup",
"Tables: customers, quotes. Per signup year (yr), return customers and pct = % of those customers with a bound quote dated 0-30 days after signup (1 decimal). Order by yr.",
"Put the date and bound conditions in the LEFT JOIN's ON clause; COUNT DISTINCT both sides.",
"SELECT EXTRACT(YEAR FROM c.signup_date)::int AS yr,\n  COUNT(DISTINCT c.customer_id) AS customers,\n  ROUND(100.0 * COUNT(DISTINCT q.customer_id) / COUNT(DISTINCT c.customer_id), 1) AS pct\nFROM customers c\nLEFT JOIN quotes q ON q.customer_id = c.customer_id AND q.bound\n  AND q.quote_date - c.signup_date BETWEEN 0 AND 30\nGROUP BY 1 ORDER BY 1;",
"Conditions in ON keep the denominator intact.",True,None),
("hard","window","Median order by country",
"Tables: orders, users. Return country and median = median amount of complete orders by the user's country (2 decimals). Order by country.",
"PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY amount).",
"SELECT u.country,\n  ROUND((PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY o.amount))::numeric, 2) AS median\nFROM orders o JOIN users u ON u.user_id = o.user_id\nWHERE o.status = 'complete'\nGROUP BY u.country\nORDER BY u.country;",
"Postgres has ordered-set aggregates (PERCENTILE_CONT/DISC, MODE). Databricks: median()/percentile_approx.",True,None),
("hard","window","Salary vs department",
"From employees, return name, dept, salary, vs_avg = salary minus dept average (0 decimals) and gap_to_next = next higher salary in the dept minus this salary (NULL for the top). Order by dept, salary desc.",
"AVG() OVER (PARTITION BY dept) and LAG(salary) OVER (PARTITION BY dept ORDER BY salary DESC, emp_id).",
"SELECT name, dept, salary,\n  ROUND(salary - AVG(salary) OVER (PARTITION BY dept)) AS vs_avg,\n  LAG(salary) OVER (PARTITION BY dept ORDER BY salary DESC, emp_id) - salary AS gap_to_next\nFROM employees\nORDER BY dept, salary DESC;",
"Multiple windows in one SELECT; name a shared one with WINDOW w AS (...).",True,None),
("hard","pivot","Report-lag triangle",
"From claims, return ay (accident year = year of loss_date) and claim counts by report lag bucket: d0_1 (0-1 days), d2_7, d8_30, d31p (31+). Order by ay.",
"Compute lag = report_date - loss_date in a subquery, then COUNT(*) FILTER per bucket.",
"SELECT EXTRACT(YEAR FROM loss_date)::int AS ay,\n  COUNT(*) FILTER (WHERE lag <= 1) AS d0_1,\n  COUNT(*) FILTER (WHERE lag BETWEEN 2 AND 7) AS d2_7,\n  COUNT(*) FILTER (WHERE lag BETWEEN 8 AND 30) AS d8_30,\n  COUNT(*) FILTER (WHERE lag > 30) AS d31p\nFROM (SELECT loss_date, report_date - loss_date AS lag FROM claims) x\nGROUP BY 1 ORDER BY 1;",
"Report-lag shapes inform IBNR.",True,None),
("hard","having","All claims closed",
"Tables: claims, policies. Return customer_id of customers with at least one claim where every claim is CLOSED. Order by customer_id.",
"HAVING BOOL_AND(status = 'CLOSED').",
"SELECT p.customer_id\nFROM claims c JOIN policies p ON p.policy_id = c.policy_id\nGROUP BY p.customer_id\nHAVING BOOL_AND(c.status = 'CLOSED')\nORDER BY p.customer_id;",
"'For all' questions: BOOL_AND in Postgres, or COUNT of violations = 0.",True,LC+"customers-who-bought-all-products/"),
("hard","sessionize","Order sessions",
"From orders, group each user's orders into sessions: a new session starts when more than 30 days passed since the user's previous order (or it's the first). Return user_id, sessions. Order by user_id.",
"LAG(order_date), flag new sessions, then SUM the flags.",
"WITH x AS (\n  SELECT user_id,\n    CASE WHEN order_date - LAG(order_date) OVER (PARTITION BY user_id ORDER BY order_date, order_id) <= 30\n         THEN 0 ELSE 1 END AS new_s\n  FROM orders)\nSELECT user_id, SUM(new_s) AS sessions\nFROM x GROUP BY user_id ORDER BY user_id;",
"Sessionization = gaps-and-islands with a threshold. The NULL from the first LAG falls to ELSE 1.",True,None),
("hard","window","First and last premium",
"From policies, per customer return customer_id, first_prem (earliest term's premium), last_prem (latest term's premium) and terms. Order by customer_id.",
"FIRST_VALUE / LAST_VALUE need a full frame, or use DISTINCT ON twice.",
"SELECT DISTINCT customer_id,\n  FIRST_VALUE(premium) OVER w AS first_prem,\n  LAST_VALUE(premium) OVER w AS last_prem,\n  COUNT(*) OVER (PARTITION BY customer_id) AS terms\nFROM policies\nWINDOW w AS (PARTITION BY customer_id ORDER BY effective_date, policy_id\n  ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING)\nORDER BY customer_id;",
"LAST_VALUE with the default frame returns the current row: the #1 window gotcha.",True,LC+"game-play-analysis-i/"),
("hard","joins","Quoted, never bound",
"Tables: customers, quotes, policies. Return names of customers with 2+ quotes, none bound, and no policies. Order by name. (An empty result can be correct; check why.)",
"GROUP BY + HAVING NOT BOOL_OR(bound) + NOT EXISTS policies.",
"SELECT c.name\nFROM customers c JOIN quotes q ON q.customer_id = c.customer_id\nWHERE NOT EXISTS (SELECT 1 FROM policies p WHERE p.customer_id = c.customer_id)\nGROUP BY c.customer_id, c.name\nHAVING COUNT(*) >= 2 AND NOT BOOL_OR(q.bound)\nORDER BY c.name;",
"An empty result is a valid answer here: every customer in the seed has a policy.",True,None),
("hard","dates","Daily and 7-day active users",
"From logins, for each distinct login_date return dau (distinct users that day) and wau7 (distinct users in the 7 days ending that day). Order by login_date.",
"Self join on l.login_date BETWEEN d.login_date - 6 AND d.login_date; COUNT(DISTINCT) FILTER for dau.",
"WITH d AS (SELECT DISTINCT login_date FROM logins)\nSELECT d.login_date,\n  COUNT(DISTINCT l.user_id) FILTER (WHERE l.login_date = d.login_date) AS dau,\n  COUNT(DISTINCT l.user_id) AS wau7\nFROM d JOIN logins l ON l.login_date BETWEEN d.login_date - 6 AND d.login_date\nGROUP BY d.login_date\nORDER BY d.login_date;",
"COUNT(DISTINCT) is not allowed as a window function in Postgres; use a range self join.",True,LC+"user-activity-for-the-past-30-days-i/"),
]
